def solve(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for char in text:
        if char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
        else:
            stack.append(char)
    return not stack

class Solution {
    public boolean isPalindrome(String text) {
        int left = 0;
        int right = text.length() - 1;
        while (left < right) {
            if (text.charAt(left) != text.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }
}

def can_make(values, target, index=0):
    if target == 0:
        return True
    if index == len(values):
        return False
    return (can_make(values, target - values[index], index + 1)
            or can_make(values, target, index + 1))

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int countReachable(boolean[][] adjacency, int start) {
        int size = adjacency.length;
        boolean[] seen = new boolean[size];
        Queue<Integer> queue = new ArrayDeque<>();
        seen[start] = true;
        queue.add(start);
        int count = 0;
        while (!queue.isEmpty()) {
            int node = queue.remove();
            count++;
            for (int neighbor = 0; neighbor < size; neighbor++) {
                if (adjacency[node][neighbor] && !seen[neighbor]) {
                    seen[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }
        return count;
    }
}

def count_paths(blocked):
    n = len(blocked)
    ways = [[0] * n for _ in range(n)]
    for row in range(n):
        for col in range(n):
            if blocked[row][col]:
                continue
            if row == 0 and col == 0:
                ways[row][col] = 1
            else:
                from_top = ways[row - 1][col] if row else 0
                from_left = ways[row][col - 1] if col else 0
                ways[row][col] = from_top + from_left
    return ways[n - 1][n - 1] if n else 0
